const defaultPruneFloorRatio = 0.5

type pruneCohort struct { Label string; Confirmed, Stored int }

// An empty cohort has nothing to lose, so it reads as fully confirmed rather
// than as 0/0 — a class stored for the first time must never refuse a prune.
func (c pruneCohort) ratio() float64 { if c.Stored <= 0 { return 1 }; return float64(c.Confirmed)/float64(c.Stored) }

func evaluatePruneFloor(floor float64, cohorts []pruneCohort) pruneFloorVerdict {
	v := pruneFloorVerdict{Asked: floor, Floor: floor, Allowed: true}
	if floor <= 0 { v.Floor = 0; v.Disabled = true; v.Clamped = floor < 0; return v }  // explicit escape hatch, recorded as such
	if floor > 1  { v.Floor = 1; v.Clamped = true }  // >1 is unsatisfiable: it would refuse every prune for ever while LOOKING like a working guard
	for _, c := range cohorts {
		r := c.ratio()
		cv := cohortVerdict{pruneCohort: c, Ratio: r, Below: r < v.Floor}  // AT the floor passes
		v.Cohorts = append(v.Cohorts, cv)
		if cv.Below { v.Failing = append(v.Failing, cv); v.Allowed = false }
	}
	sort.SliceStable(...)  // worst ratio first, so a truncated log line still names the most alarming cohort
	return v
}

