func (s codeIndexScope) mixedCommitNote() string {
	if s.err != nil || s.commits <= 1 { return "" }
	return "!! INDEX NOT AT ONE COMMIT: the N symbols in scope span M different indexed commits, so the freshness line above describes the NEWEST of them, not all of them ... Usual cause: an indexing run whose prune was REFUSED (its floor was not met) or skipped ... Treat a match on an older row as possibly-superseded, and an empty answer as UNKNOWN. !!"
}
